// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves collisions between the ball and bricks. 
// It handles per-face bouncing, push-out to avoid sticky bounces, and
// ensures only one brick is hit per call to avoid seam issues.
export function resolveBrickCollisions(state) {
  const { ball, bricks } = state;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    if (collides(ball, brick)) {
      const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
      const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

      if (Math.abs(overlapX - overlapY) < 0.01) {
        // Corner hit: flip both
        ball.vx = -ball.vx;
        ball.vy = -ball.vy;
      } else if (overlapX < overlapY) {
        // Side hit: flip vx and push out
        if (ball.vx > 0) {
          ball.vx = -Math.abs(ball.vx);
          ball.x = brick.x - ball.r;
        } else {
          ball.vx = Math.abs(ball.vx);
          ball.x = brick.x + brick.w + ball.r;
        }
      } else {
        // Top/Bottom hit: flip vy and push out
        if (ball.vy > 0) {
          ball.vy = -Math.abs(ball.vy);
          ball.y = brick.y - ball.r;
        } else {
          ball.vy = Math.abs(ball.vy);
          ball.y = brick.y + brick.h + ball.r;
        }
      }

      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      break;
    }
  }
}

